1269	\begin{corollary}[Prescribed extraction under variable agreement]
1270	  \label{cor:ms-rigidity-prescribed-answers}
1271	  \lean{MIPStarRE.QPBT.exists_ms_rigidity_prescribed_answers}
1272	  \leanok
1273	  \uses{lem:ms-prescribed-separate-errors, def:ms-variable-agreement}
1274	  There is a universal constant $C=2\cdot10^{13}$ such that, for every
1275	  $\eps,\delta\ge0$ and every strategy of value at least $1-\eps$ with
1276	  $\Delta_1,\Delta_5\le\delta$, one witness satisfies all seven printed
1277	  quantities, using prescribed effects, at most
1278	  $C(\sqrt\eps+\sqrt\delta)$. The state quantity is Euclidean and the six
1279	  operator quantities are squared distances on the ideal state. This is an
1280	  explicitly restricted corollary; it does not prove the unrestricted
1281	  proposition of Definition~\ref{def:ms-rigidity-printed-claim}.
1282	\end{corollary}
1283	\begin{proof}
1284	  \leanok
1285	  \uses{lem:ms-prescribed-separate-errors}
1286	  Apply the preceding lemma with $\min(\eps,1)\le\sqrt\eps$.
1287	  The completed agreement distances are at most $8$, so the two agreement
1288	  hypotheses imply $\Delta_j\le8\sqrt\delta$ for every $\delta\ge0$.
1289	\end{proof}
1373	\begin{lemma}[Formalization support for the large-error regime]\label{lem:ms-rigidity-support-constants}
1374		\lean{MIPStarRE.QPBT.MagicSquareRigidity.registerFiberEmbeddingMap, MIPStarRE.QPBT.MagicSquareRigidity.registerFiberEmbedding, MIPStarRE.QPBT.MagicSquareRigidity.registerFiberEmbedding_apply, MIPStarRE.QPBT.MagicSquareRigidity.conjTranspose_mul_le_one_neg, MIPStarRE.QPBT.MagicSquareRigidity.opFamilyDistSq_uniform_unit_binary_le, MIPStarRE.QPBT.MagicSquareRigidity.opDistSq_uniform_unit_le}
1375		\leanok
1376		\uses{def:povm-distance, def:EPR}
1377		None of the following is a named statement of the source article; each isolates one step of the Lean proof of Theorem~\ref{thm:ms-rigidity}. Once $\sqrt\eps + \sqrt\delta \ge 1$ the conclusion of Theorem~\ref{thm:ms-rigidity} is carried by estimates available for any witness: two unit vectors are at distance at most $2$; the squared state-dependent distance of Definition~\ref{def:povm-distance} between two contractions on a unit vector is at most $4$, so a two-outcome family has squared distance at most $8$ under the one-point distribution. A witness exists for every strategy, namely the embedding of a local space as the fibre of the extracted register over one fixed basis vector, which is an isometry.
1378	\end{lemma}
1379	\begin{proof}
1380		\leanok
1381		\uses{def:povm-distance}
